// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {airdrop} from "../src/airdrop.sol";

contract InvMutTest is Test {
    airdrop c;
    function setUp() public { c = new airdrop(); }

    // Fuzzed parameter: an address candidate for `from` and an uint v; the crucial deciding input is the zero-length recipients array,
    // which the fuzzer does not need to supply (we construct it). We fuzz `from` to keep inputs varied.
    function testFuzz_property(address from, uint256 v) public {
        // keep `from` non-zero to be a reasonable actor (still wide)
        vm.assume(from != address(0));

        // Build an empty recipients array to exercise the boundary the mutant changed.
        address[] memory tos = new address[](0);

        // Call transfer and observe whether it reverts (ok == false) or returns successfully (ok == true).
        bool ok;
        try c.transfer(from, address(0x1234567890123456789012345678901234567890), tos, v) {
            ok = true;
        } catch {
            ok = false;
        }

        // GENERAL RULE ASSERTION:
        // The reference implementation always reverts for an empty `_tos` array, so ok MUST be false for ALL inputs.
        // The mutant that removed the require will sometimes return true (ok == true) for the empty array,
        // making this assertion fail on that buggy variant.
        assertTrue(ok == false);
    }
}
